    landmarkChange={cleared:0,primed:0};for(const item of [...landmarks])if(Math.hypot(item.x-c.x,item.y-c.y)<1.05){const ix=clamp(Math.floor(item.x),0,N-1),iy=clamp(Math.floor(item.y),0,N-1),wasPrimed=item.raisedForClearance,result=applyLandmarkShaping(item,delta,tileHeight(ix,iy)<=water+.05);if(result.cleared){landmarks.splice(landmarks.indexOf(item),1);landmarkChange.cleared+=1;}else{Object.assign(item,result.landmark);if(!wasPrimed&&item.raisedForClearance)landmarkChange.primed+=1;}}settlementChange=reconcileSettlements();return true;
