  function usePower(name,t){
    if(name==="armageddon"&&!matchVariantRule(matchVariant).reckoning){say("Reckoning is sealed in Mortal Contest. Win through ordinary conquest.");return;}
    if(paused){say("Resume the world before invoking a power.");selectPower(null);return;}
    const globalPower=name==="champion"||name==="flood"||name==="armageddon";if(!globalPower&&!t)return; const cost=COST[name];if(!spend(cost)){selectPower(null);return;}
    if(name==="quake"){battleFx.push({type:"quake",x:t.x+.5,y:t.y+.5,age:0,life:2.2,color:"#e8a45d"});clearLandmarksNear(t.x+.5,t.y+.5,3.4,"tree");for(let i=0;i<22;i++){const x=clamp(t.x+Math.floor(rand(-3,4)),0,N),y=clamp(t.y+Math.floor(rand(-3,4)),0,N),magnitude=Math.random()<.24?2:1;heights[y][x]=clamp(heights[y][x]+(Math.random()<.54?-magnitude:magnitude),0,7);}addBoulderField(t.x,t.y,3.1,worldRule(currentWorld).quakeRocks,true);const drowned=drownFloodedPeople(t,3.6),result=reconcileSettlements();playCue("earthquake");say(`The earth breaks; trees fall and new stone scars the land${currentWorld===2?" in a heavy field":""}. Unsupported dwellings shrink or fall.${drowned?` ${drowned} ${drowned===1?"walker drowns":"walkers drown"} in the shattered ground.`:""}${describeSettlementChange(result)}`,true);}
    if(name==="bog"){for(const cell of powerAffectedCells("bog",t,N))bogs.add(`${cell.x},${cell.y}`);say("A hungry bog stains the earth.");}
    if(name==="champion"){const leader=people.find(p=>p.faction==="player"&&p.leader)||people.find(p=>p.faction==="player");if(leader){leader.leader=true;leader.champion=true;leader.hp=Math.max(leader.hp,120);order="roam";setOrderIndicator("Champion hunt");playCue("lightning");say("Your leader becomes a champion and hunts Veyra's settlements.");}}
    if(name==="flood"){water=Math.min(4,water+1);const result=reconcileSettlements();playCue("impact");say(`The waters climb; flooded foundations are abandoned.${describeSettlementChange(result)}`,true);}
    if(name==="volcano"){battleFx.push({type:"volcano",x:t.x+.5,y:t.y+.5,age:0,life:2.8,color:"#ff8b46"});clearLandmarksNear(t.x+.5,t.y+.5,3.8);for(const cell of powerAffectedCells("volcano",t,N)){const d=Math.hypot(cell.x-t.x,cell.y-t.y);heights[cell.y][cell.x]=clamp(heights[cell.y][cell.x]+Math.max(1,Math.round(4-d)),0,7);}addBoulderField(t.x,t.y,3.4,15,true);const forced=evacuateSettlements(t,3.5),result=reconcileSettlements();playCue("volcano");say(`A volcano destroys ${forced.destroyed} ${forced.destroyed===1?"settlement":"settlements"}; ${forced.evacuated} residents flee and ${forced.lost} are lost. The crater remains choked with stone.${describeSettlementChange(result)}`,true);}
    if(name==="armageddon"){order="reckoning";reckoningAt=elapsed;reckoningTick=0;reckoningPhase="march";beacon={x:N/2,y:N/2};for(const resident of releaseForReckoning(houses))spawn(resident.faction,resident.x,resident.y);houses=[];for(const p of people){raiseReckoningRoute(p);p.tx=N/2+rand(-1.4,1.4);p.ty=N/2+rand(-1.4,1.4);p.retarget=0;p.settle=999;}camera.x=N/2;camera.y=N/2;camera.zoom=1.35;applyZoom();updateCameraReadout();setOrderIndicator("Reckoning");setMusicScene("reckoning");playCue("reckoning");say("The Reckoning begins. Every soul abandons shelter and marches to the world's heart.",true);$("#toast").classList.remove("show");}
    selectPower(null);hoverCorner=null;pointerView.inside=false;updateUI();
  }

  function update(dt){
    if(paused||over)return;elapsed+=dt;if(artTestMode||previewTestMode){updateUI();return;} const step=dt*speed;simElapsed+=step; mana=Math.min(999,mana+step*manaIncome(houses,"player"));rivalMana=Math.min(999,rivalMana+step*manaIncome(houses,"rival"));if(frontierTestMode)rival2Mana=Math.min(999,rival2Mana+step*manaIncome(houses,"rival2"));
    const tideRule=worldRule(currentWorld);while(tideRule.tideTimes&&worldTideWarningStage<tideRule.tideTimes.length&&simElapsed>=tideRule.tideTimes[worldTideWarningStage]-12){worldTideWarningStage+=1;say(`Tide warning: low ground floods in 12 seconds on both sides. Seek or shape higher land.`,"notice");}while(tideRule.tideTimes&&worldTideStage<tideRule.tideTimes.length&&simElapsed>=tideRule.tideTimes[worldTideStage]){worldTideStage+=1;water=Math.min(4,water+tideRule.tideRise);const result=reconcileSettlements(),exposed=people.filter(person=>tileHeight(clamp(Math.floor(person.x),0,N-1),clamp(Math.floor(person.y),0,N-1))<=water).length;playCue("catastrophe");say(`Tide ${worldTideStage} of ${tideRule.tideTimes.length}: the vale floods for both peoples.${exposed?` ${exposed} ${exposed===1?"walker stands":"walkers stand"} in weakening floodwater.`:""}${describeSettlementChange(result)}`,true);}
    updateHouses(step); updatePeople(step);if(frontierEconomy)for(const person of people)if(person.faction==="player")revealFog(frontierEconomy.explored,N,person.x,person.y,4);if(order==="reckoning")updateReckoning(step);while(order!=="reckoning"&&simElapsed>=nextRivalAct){rivalAct();if(frontierTestMode)orunAct();nextRivalAct+=5;}for(const fx of battleFx)fx.age+=step;battleFx=battleFx.filter(fx=>fx.age<fx.life);
    const pp=population("player"),rp=population("rival"),result=frontierTestMode?multiFactionOutcome({player:pp,rival:rp,rival2:population("rival2")},elapsed):terminalOutcome(pp,rp,elapsed);if(result!==null)finish(result);if(elapsed>=statusLockUntil&&statusQueue.length){const queued=statusQueue.shift();say(queued.message,queued.priority,queued.target);}if(elapsed-lastUiRefresh>=.2){updateUI();lastUiRefresh=elapsed;}
  }

  function updateReckoning(dt){const since=elapsed-reckoningAt;if(since<7){reckoningPhase="march";return;}reckoningPhase="clash";reckoningTick+=dt;for(const p of people){p.combatUntil=elapsed+.35;p.tx=N/2+rand(-1.2,1.2);p.ty=N/2+rand(-1.2,1.2);}while(reckoningTick>.22){reckoningTick-=.22;const factions=activeFactionDefs().map(def=>def.id),fighters=Object.fromEntries(factions.map(id=>[id,people.filter(p=>p.faction===id)])),populations=Object.fromEntries(factions.map(id=>[id,fighters[id].reduce((sum,p)=>sum+bandSize(p),0)])),living=factions.filter(id=>populations[id]>0);if(living.length<2)return;const losingFaction=chooseReckoningLoss(populations,Math.random()),pool=fighters[losingFaction],soul=Math.floor(Math.random()*populations[losingFaction]);let cursor=0,loss=pool[0];for(const band of pool){cursor+=bandSize(band);if(soul<cursor){loss=band;break;}}loseBandMember(loss);const winnerPool=people.filter(p=>p.faction!==losingFaction);if(winnerPool.length){const foe=winnerPool[Math.floor(Math.random()*winnerPool.length)];addBattleFx((loss.x+foe.x)/2,(loss.y+foe.y)/2,"hit");}if(Math.random()<.18){const vx=clamp(Math.round(N/2+rand(-2,2)),0,N),vy=clamp(Math.round(N/2+rand(-2,2)),0,N);heights[vy][vx]=clamp(heights[vy][vx]+(Math.random()<.5?-1:1),0,7);}}}

  function raiseReckoningRoute(p){const steps=Math.ceil(Math.hypot(p.x-N/2,p.y-N/2)*2),level=Math.ceil(water+1);for(let i=0;i<=steps;i++){const t=i/Math.max(1,steps),x=clamp(Math.floor(p.x+(N/2-p.x)*t),0,N-1),y=clamp(Math.floor(p.y+(N/2-p.y)*t),0,N-1);if(tileHeight(x,y)<=water)for(const [vx,vy] of [[x,y],[x+1,y],[x,y+1],[x+1,y+1]])heights[vy][vx]=Math.max(heights[vy][vx],level);}}

  function emitDwellingFollower(h){const active=people.filter(p=>p.faction===h.faction),limit=activeBandLimit();if(active.length<limit){spawn(h.faction,h.x+rand(-.3,.3),h.y+rand(-.3,.3));return true;}const target=active.filter(p=>!p.leader&&!p.champion&&bandSize(p)<4).sort((a,b)=>dist(a,h)-dist(b,h))[0];if(target){target.members=bandSize(target)+1;target.hp=Math.min(target.members*18,target.hp+10);addBattleFx(target.x,target.y,"merge",colors[h.faction]);return true;}h.pop+=1;return false;}

  function updateHouses(dt){
    if(frontierEconomy){refreshFrontierFarms();for(const faction of activeFactionDefs().map(def=>def.id)){const factionHouses=houses.filter(h=>h.faction===faction),factionPeople=people.filter(p=>p.faction===faction),farms=frontierEconomy.farms.filter(farm=>farm.faction===faction&&farm.active===true),workers=farms.filter(farm=>factionPeople.some(p=>p.job==="food"&&dist(farm,p)<.75)).length;advanceFoodEconomy(frontierEconomy.stock[faction],{walkers:factionPeople.length,houses:factionHouses.length,residents:factionHouses.reduce((sum,h)=>sum+h.pop,0),farms:farms.length,workers,dt});}}const orderedHouses=frontierEconomy?[...houses].sort((a,b)=>a.faction.localeCompare(b.faction)||a.y-b.y||a.x-b.x):houses;for(const h of orderedHouses){h.grow+=dt;h.hp=Math.min(20+h.level*10,h.hp+dt*.3);if(frontierEconomy&&frontierEconomy.stock[h.faction].food<=0){h.grow=Math.max(0,h.grow-dt*.7);continue;}if(h.grow>dwellingGrowthInterval(h.level)*(frontierEconomy?2.2:1)){const emitted=advanceDwelling(h);if(frontierEconomy)frontierEconomy.stock[h.faction].food=Math.max(0,frontierEconomy.stock[h.faction].food-(1.5+h.level*.5));if(emitted)emitDwellingFollower(h);h.grow=0;}}if(frontierEconomy&&simElapsed>=frontierEconomy.nextFarmAt){buildFrontierFarms();buildFrontierCauseways();frontierEconomy.nextFarmAt=simElapsed+15;}
  }

  function farmRouteLength(home,farm){const blocked=(x,y)=>landmarks.some(item=>Math.floor(item.x)===x&&Math.floor(item.y)===y&&landmarkBlocksPath(item));return boundedFarmRoute({start:home,goal:farm,radius:12,canEnter:(x,y,current)=>x>=0&&y>=0&&x<N&&y<N&&dry(x,y)&&Math.abs(tileHeight(x,y)-tileHeight(current.x,current.y))<=1.6&&!blocked(x,y),diagonalClear:(current,dx,dy)=>!blocked(current.x+dx,current.y)&&!blocked(current.x,current.y+dy)});}
  function refreshFrontierFarms(){frontierEconomy.farmValidationCursor=refreshFarmBatch({farms:frontierEconomy.farms,cursor:frontierEconomy.farmValidationCursor||0,budget:2,now:simElapsed,isDry:item=>dry(clamp(Math.floor(item.x),0,N-1),clamp(Math.floor(item.y),0,N-1)),routeLength:item=>{const homes=houses.filter(h=>h.faction===item.faction&&dist(h,item)<=12).sort((a,b)=>dist(a,item)-dist(b,item));if(!homes.length){item.homeCheck=0;return Infinity;}const index=Math.min(item.homeCheck||0,homes.length-1),route=farmRouteLength(homes[index],item);if(Number.isFinite(route)){item.homeCheck=0;return route;}item.homeCheck=index+1;if(item.homeCheck>=homes.length){item.homeCheck=0;return Infinity;}return null;}});}

  function buildFrontierFarms(){for(const faction of activeFactionDefs().map(def=>def.id)){const stock=frontierEconomy.stock[faction];if(stock.wood<28||frontierEconomy.farms.filter(farm=>farm.faction===faction).length>=houses.filter(house=>house.faction===faction).length)continue;const homes=houses.filter(house=>house.faction===faction);let site=null;for(const home of homes)for(let step=0;step<12&&!site;step++){const angle=step*Math.PI/6,x=clamp(Math.floor(home.x+Math.cos(angle)*2.2),0,N-1),y=clamp(Math.floor(home.y+Math.sin(angle)*2.2),0,N-1),point={x:x+.5,y:y+.5};if(isFlat(x,y)&&dry(x,y)&&!houses.some(h=>dist(h,point)<1.4)&&!landmarks.some(item=>dist(item,point)<1)&&!frontierEconomy.nodes.some(node=>node.amount>0&&dist(node,point)<1.2)&&!frontierEconomy.farms.some(farm=>dist(farm,point)<1.5))site=point;}if(site){stock.wood-=28;frontierEconomy.farms.push({...site,faction});}}}
  function buildFrontierCauseways(){if(!frontierEconomy.ocean)return;const links=[["player","rival"],["rival","rival2"],["rival2","player"]];for(const [from,to] of links){const key=[from,to].sort().join("-");if(frontierEconomy.causeways.includes(key))continue;const cells=causewayCells(factionStarts[from],factionStarts[to],N),isSubmerged=cell=>tileHeight(clamp(cell.x,0,N-1),clamp(cell.y,0,N-1))<=water,submerged=cells.filter(isSubmerged),deck=causewayDeckCells(cells,isSubmerged,2),cost=submerged.length*3,stock=frontierEconomy.stock[from];if(!submerged.length){frontierEconomy.causeways.push(key);continue;}if(stock.wood<cost||stock.priorities.build<15||deck.some(cell=>houses.some(h=>dist(h,{x:cell.x+.5,y:cell.y+.5})<1.6)))continue;stock.wood-=cost;const level=Math.ceil(water+1);for(const cell of deck)for(const [vx,vy] of [[cell.x,cell.y],[Math.min(N,cell.x+1),cell.y],[cell.x,Math.min(N,cell.y+1)],[Math.min(N,cell.x+1),Math.min(N,cell.y+1)]])heights[vy][vx]=level;const deckKeys=new Set(deck.map(cell=>`${cell.x},${cell.y}`));landmarks=landmarks.filter(item=>!deckKeys.has(`${Math.floor(item.x)},${Math.floor(item.y)}`));frontierEconomy.causeways.push(key);say(`${factionName(from)} completed a timber causeway across open water.`,true,factionStarts[from]);}}

  function flatArea(cx,cy){return connectedFlatArea(cx,cy);}
